import django
from django.conf import settings

settings.configure(
    DEBUG=True,
    DATABASES={"default": {"ENGINE": "django.db.backends.sqlite3", "NAME": ":memory:"}},
    INSTALLED_APPS=["django.contrib.contenttypes", "django.contrib.auth"],
    USE_TZ=True,
)
django.setup()

from django.db import models, connection
from django.db.migrations.state import ProjectState
from django.db.migrations.autodetector import MigrationAutodetector
from django.db.migrations import Migration
from django.apps.registry import Apps as RegApps


class AccountOld(models.Model):
    class Meta:
        app_label = "manage"


class AddressOld(models.Model):
    account = models.OneToOneField(AccountOld, on_delete=models.CASCADE)

    class Meta:
        app_label = "manage"


class ProfileOld(models.Model):
    account = models.ForeignKey(
        "AccountOld", null=True, blank=True, on_delete=models.CASCADE
    )

    class Meta:
        app_label = "manage"


class Account(models.Model):
    id = models.CharField(primary_key=True, db_collation="utf8_bin", max_length=22)

    class Meta:
        app_label = "manage"


class Address(models.Model):
    id = models.CharField(primary_key=True, db_collation="utf8_bin", max_length=22)
    account = models.OneToOneField(Account, on_delete=models.CASCADE)

    class Meta:
        app_label = "manage"


class Profile(models.Model):
    id = models.CharField(primary_key=True, db_collation="utf8_bin", max_length=22)
    account = models.ForeignKey(
        "Account", null=True, blank=True, on_delete=models.CASCADE
    )

    class Meta:
        app_label = "manage"


def make_state(*model_list):
    st = ProjectState()
    for m in model_list:
        st.add_model(m)
    return st


before = make_state(AccountOld, AddressOld, ProfileOld)
after = make_state(Account, Address, Profile)

autodetector = MigrationAutodetector(before, after)
changes = autodetector._detect_changes()
ops = []
for app_label, miglist in changes.items():
    for mig in miglist:
        ops.extend(mig.operations)
migration = Migration("test", "manage")
migration.operations = ops

with connection.schema_editor(atomic=False) as editor:
    for m in (AccountOld, AddressOld, ProfileOld):
        editor.create_model(m)
    state = before.clone()
    for op in ops:
        new_state = state.clone()
        op.state_forwards("manage", new_state)
        op.database_forwards("manage", editor, state, new_state)
        state = new_state
    print("---- deferred SQL (constraints etc.) ----")
    for s in editor.deferred_sql:
        print(s)

print("---- final introspected collations ----")
with connection.cursor() as cur:
    for table, col in (
        ("manage_account", "id"),
        ("manage_address", "account_id"),
        ("manage_profile", "account_id"),
    ):
        coll = next(
            (
                f.collation
                for f in connection.introspection.get_table_description(cur, table)
                if f.name == col
            ),
            None,
        )
        print(f"{table}.{col}: {coll}")

ok = True
