    ):
        coll = next(
            (
                f.collation
                for f in connection.introspection.get_table_description(cur, table)
                if f.name == col
            ),
            None,
        )
        if coll != "utf8_bin":
            ok = False
            print(f"FAIL: {table}.{col} collation is {coll!r}, expected 'utf8_bin'")
print("RESULT:", "PASS" if ok else "FAIL")
